import sys
from test.support import open_urlresource, requires_resource, script_helper, cpython_only, check_disallow_instantiation, force_not_colorized, is_resource_enabled, findfile
quicktest = not is_resource_enabled('cpu')

def iterallchars():
    maxunicode = 65535 if quicktest else sys.maxunicode
    return map(chr, range(maxunicode + 1))

def _t():
    for c in iterallchars():
        lines = (c + 'A').splitlines()
        if c in ('\n', '\x0b', '\x0c', '\r', '\x85', '\x1c', '\x1d', '\x1e', '\u2028', '\u2029'):
            assert len(lines) == 2, ('assertEqual', len(lines), 2)
        else:
            assert len(lines) == 1, ('assertEqual', len(lines), 1)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

